                t.match(barDep.browser, /bar\.css$/);
                t.match(barDep.main, /bar\.css$/);

                const bazDep = deps['./baz.css'];
                t.match(
                    bazDep.browser,
                    /baz\.css$/,
                    'media query suffix is stripped from the import target'
                );
                t.match(bazDep.main, /baz\.css$/);
            });
        });
