const { default: chalk } = require('chalk');
const MendelPipelineDaemon = require('./daemon');
const MendelClient = require('./client/build-all');

class Mendel {
    static get Daemon() {
        return MendelPipelineDaemon;
    }

    static get Client() {
        return MendelClient;
    }

    constructor(config) {
        this.daemon = new Mendel.Daemon(config);
        this.client = new Mendel.Client(
            Object.assign(
                {
                    verbose: false,
                },
                config
            )
        );
    }

    run(callback) {
        this.daemon.run((error) => {
            if (error) {
                if (error instanceof ReferenceError) {
                    console.warn(
                        chalk.yellow(
                            [
                                '[Mendel] Instance of builder may be running.',
                                'Attemping to recycle...',
                            ].join('\n')
                        )
                    );
                } else {
                    console.error(
                        '[Mendel] Unknown builder execution error: ',
                        error
                    );
                    process.exit(1);
                }
            }
            this.client.run((error) => {
                if (error) return callback(error);
                setImmediate(() => callback());
            });
        });
    }

    onForceExit() {
        this.daemon.onForceExit();
    }
}

module.exports = Mendel;

#!/usr/bin/env node
/* eslint max-len: "off" */
const { Command } = require('commander');
const { default: chalk } = require('chalk');

const program = new Command();

function stringCollection(val = '', collection) {
    return collection.concat(
        val
            .split(',')
            .map((splitted) => splitted.trim())
            .filter(Boolean)
    );
}

program
    .version('0.1.0')
    .usage('[options]')
    .option(
        '-i, --ignore <patterns>',
        'Comma separated ignore glob patterns',
        stringCollection,
        []
    )
    // .option('-v, --verbose', 'Verbose mode')
    .option('-w, --watch', 'Watch mode', false)
    .option(
        '-l, --only <ids>',
        'Only build this list of bundleIds',
        stringCollection,
        []
    )
    .option('-o, --outlet', 'Write a mendel v1 compatible manifest', false)
    .parse(process.argv);

const opts = program.opts();
opts.ignores = opts.ignore;

if (opts.watch) {
    const MendelPipelineDaemon = require('./daemon');
    const daemon = new MendelPipelineDaemon(opts);
    daemon.watch();
} else {
    const Mendel = require('./main');
    const daemon = new Mendel(opts);
    daemon.run((error) => {
        if (error) process.exit(1);
        setImmediate(() => process.exit(0));
    });

    const AnalyticsCliPrinter = require('./helpers/analytics/cli-printer');
    const collector = require('./helpers/analytics/analytics-collector');
    collector.setOptions({
        printer: new AnalyticsCliPrinter({ enableColor: true }),
    });

    process.on('exit', (code) => {
        if (code > 0) {
            daemon.onForceExit();
        }
    });

    process.on('SIGINT', () => {
        console.error('SIGINT');
        daemon.onForceExit();
        process.exit(1);
    });

    process.on('uncaughtException', (error) => {
        console.error(
            [
                `Force closing due to a critical error:\n`,
                chalk.red(error.stack),
            ].join(' ')
        );
        daemon.onForceExit();
        process.exit(1);
    });

    // nodemon style shutdown
    process.once('SIGUSR2', () => process.kill(process.pid, 'SIGUSR2'));
}

const BaseNetwork = require('./base-network');
const net = require('net');
const fs = require('fs');
const { resolve } = require('path');
const { default: chalk } = require('chalk');
const verbose = require('debug')('verbose:mendel:net:unix-socket');

function patchSocket(socket) {
    const realWrite = net.Socket.prototype.write;
    // Consistent API as WS or others this way.
    const realEmit = net.Socket.prototype.emit;
    const CONTENT_DELIMITER = '\u0004';
    let buffer = '';
    socket.send = function (str) {
        if (typeof str === 'object') str = JSON.stringify(str);
        this.write(str);
    };

    socket.write = function (str) {
        // end of transmission
        realWrite.call(this, str + CONTENT_DELIMITER);
    };

    socket.emit = function (name, content) {
        if (name !== 'data') return realEmit.apply(this, arguments);

        let delimitInd;
        while ((delimitInd = content.indexOf(CONTENT_DELIMITER)) >= 0) {
            realEmit.call(this, 'data', buffer + content.slice(0, delimitInd));
            content = content.slice(delimitInd + CONTENT_DELIMITER.length);
            buffer = '';
        }

        buffer += content;
    };
}

class UnixSocketNetwork extends BaseNetwork {
    static _serverPrecondition(path) {
        path = resolve(path);
        try {
            fs.statSync(path);
        } catch (err) {
            // File descriptor does not exist. Good to go!
            verbose('file descriptor not found, starting server');
            return Promise.resolve();
        }
        verbose('file descriptor FOUND, connecting for double checking');

        return (
            new Promise((resolve, reject) => {
                const client = this.getClient({ path });
                client.unref();
                client.once('connect', () => {
                    verbose('able to connect, client really alive');
                    client.end();
                    reject(new Error('FOREIGN_SERVER'));
                });
                client.once('error', () => {
                    verbose('server irresponsive, starting server');
                    resolve();
                });
            })
                // If connection was not made, try to delete the ipc file.
                .then(() => fs.unlinkSync(path))
                // If connection was made OR unlink was unsuccessful
                // throw and exit -- cannot recover.
                .catch((error) => {
                    if (error.message === 'FOREIGN_SERVER') {
                        console.error(
                            chalk.red(
                                [
                                    '==================================================',
                                    '[Mendel][Error] Another builder is already running.',
                                    'If no server process is active, ',
                                    `please remove or kill "${chalk.bold(
                                        path
                                    )}" manually.`,
                                    '==================================================',
                                ].join('\n')
                            )
                        );
                        throw new ReferenceError('Other Daemon Active');
                    }
                    throw error;
                })
        );
    }

    // @override
    static getServer(connectionOptions) {
        const { path } = connectionOptions;

        return this._serverPrecondition(path).then(() => {
            const server = net.createServer().listen({ path });
            let isClosed = false;
            let close = server.close;

            server.on('connection', (socket) => {
                patchSocket(socket);
                socket.setEncoding('utf8');
            });
            server.on('close', () => (isClosed = true));
            server.close = function closeHelper() {
                // Cannot close already closed socket.
                // Socket should tell us instead :(
                if (isClosed) return;
                close.call(server);
            };
            server.once('error', (err) => {
                console.error('Unrecoverable Server Error', err);
                process.exit(1);
            });

            return server;
        });
    }

    // @override
    static getClient(connectionOptions) {
        verbose('client with options', connectionOptions);
        const connection = net.connect(connectionOptions);
        patchSocket(connection);
        connection.setEncoding('utf8');
        return connection;
    }
}

module.exports = UnixSocketNetwork;

const BasePrinter = require('./printer');
const { default: chalk } = require('chalk');
const { default: prettyMs } = require('pretty-ms');
const { default: figure } = require('figures');

function getBarText(percent, maxBarSize) {
    maxBarSize = Math.max(0, maxBarSize);
    const barNumber = Math.max(Math.ceil((percent / 100) * maxBarSize), 1);
    return (
        chalk.blue(new Array(barNumber + 1).join(figure.square)) +
        chalk.blue.dim(
            new Array(Math.max(0, maxBarSize - barNumber + 1)).join(
                figure.square
            )
        )
    );
}

function padLeft(str, width) {
    return new Array(Math.max(0, width - str.length + 1)).join(' ') + str;
}

function padRight(str, width) {
    return str + new Array(Math.max(0, width - str.length + 1)).join(' ');
}

class CliPrinter extends BasePrinter {
    constructor(options = {}) {
        super(options);

        chalk.level = options.enableColor !== false ? 3 : 0;
        this.processStart = Date.now();

        this.nameMaxLen = options.nameMaxLen || 30;
    }

    groupData(data, columnIndex) {
        const grouping = {};

        data.forEach((point) => {
            const columnName = point.name.split(':')[columnIndex];
            grouping[columnName] = grouping[columnName] || [];

            grouping[columnName].push(point);
        });

        return grouping;
    }

    _print(data, dimensions, indentation = 0) {
        const [dimension] = dimensions;
        const subData = this.groupData(data, dimension);

        if (dimensions.length > 1) {
            return Object.keys(subData).forEach((groupedName) => {
                const dataPart = subData[groupedName];

                console.log(
                    new Array(indentation + 1).join('  ') +
                        chalk.underline(groupedName)
                );
                this._print(dataPart, dimensions.slice(1), indentation + 1);
            });
        }

        // Group/aggregate the data
        const points = Object.keys(subData)
            .map((groupedName) => {
                const dataPart = subData[groupedName];

                // Special case: make the labels pretty!
                if (
                    indentation === 0 &&
                    dimensions.length === 1 &&
                    dimension !== 1
                ) {
                    // Example: <pid> (groupNameA+groupNameB+groupNameC+etc…)
                    const set = new Set();
                    dataPart.forEach((p) => set.add(p.name.split(':')[1]));
                    const groupNames =
                        Array.from(set.keys()).sort().slice(0, 3).join('+') +
                        (set.size > 3 ? '+etc…' : '');
                    groupedName += ` (${groupNames})`;
                }
                const aggregate = dataPart.reduce(
                    (reduced, point) => reduced + point.after - point.before,
                    0
                );
                return { name: groupedName, aggregate };
            })
            .sort((a, b) => b.aggregate - a.aggregate);

        // Sum all time in this particular group for percentage
        const totalAggregateTime = points.reduce(
            (reduced, { aggregate }) => reduced + aggregate,
            0
        );

        // Textify
        const tabledText = points
            .map(({ name, aggregate }) => {
                const percent = totalAggregateTime
                    ? (aggregate / totalAggregateTime) * 100
                    : 0;
                // 7 for the time string, 4 for percent string, 3 to compensate for column char of the table
                const maxBarSize =
                    (process.stdout.columns || 80) -
                    this.nameMaxLen -
                    7 -
                    4 -
                    6;
                return [
                    // maximum of 20
                    padRight(
                        new Array(indentation + 1).join('  ') +
                            name.slice(0, this.nameMaxLen),
                        this.nameMaxLen
                    ),
                    // max of 7 characters
                    padLeft(prettyMs(aggregate).slice(0, 7), 7),
                    getBarText(percent, maxBarSize),
                    // maximum of 4 character (number + '%')
                    padLeft(`${Math.round(percent)}%`, 4),
                ].join('  ');
            })
            .join('\n');

        // Print the table!
        console.log(tabledText);
    }

    print(data) {
        console.log(
            chalk.bgWhite.black(
                padRight(
                    ' Sorted by grouping (aggregate of all thread)',
                    process.stdout.columns || 80
                )
            )
        );
        this._print(data, [1]);

        console.log(
            chalk.bgWhite.black(
                padRight(' Sorted by subgroup', process.stdout.columns || 80)
            )
        );
        this._print(data, [1, 2]);

        console.log(
            chalk.bgWhite.black(
                padRight(' Sorted by pid', process.stdout.columns || 80)
            )
        );
        this._print(data, [0]);

        console.log(
            new Array((process.stdout.columns || 80) + 1).join(figure.line)
        );
        console.log(
            chalk.white(
                `Process finished in ${chalk.bold(
                    prettyMs(Date.now() - this.processStart)
                )}.`
            )
        );
    }
}

module.exports = CliPrinter;

